// The tracking screens' routes, as typed `Href`s. expo-router's typed routes are generated by the dev server into
// .expo/types (git-ignored), so a freshly added screen is unknown to the type checker until that has run; casting here keeps
// `tsc` independent of that generated file.
import type { Href } from 'expo-router';

import type { SetupStepId } from './onboarding';

export const trackingRoutes = {
  setup: (step?: SetupStepId): Href =>
    (step ? { pathname: '/tracking-setup', params: { step } } : '/tracking-setup') as unknown as Href,
  health: '/tracking-setup/health' as unknown as Href,
  journeys: '/my-journeys' as unknown as Href,
  journey: (id: number): Href => ({ pathname: '/my-journeys/[id]', params: { id: String(id) } }) as unknown as Href,
};
